# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/41p_mediation_quadratic_lagged.R
# 41p_mediation_quadratic_lagged.R
#
# PJ, 14 Sep 2026: caught that Figure 3.7's mediation model (41o/build_fig_
# 3_7_mediation.R) was CONTEMPORANEOUS - prof_pc1, trust_pct and turb_pc1 all
# joined on the same year, no lag anywhere. "should be lagged - please re
# do." Then specified the actual structure wanted: "need to work out the
# structure of the lags -2 for prof and -1 for trust" - i.e. a genuine
# SEQUENTIAL mediation chain, not a single shared lag applied uniformly:
#
#   Professionalisation(t-2) --a--> Trust(t-1) --b--> Turbulence(t)
#                            \______________c/c'______________/
#
# Professionalisation changes, 2 years later trust has moved (path a), and
# trust's level 1 year before turbulence is what predicts turbulence
# (path b) - so the mediator sits exactly 1 year ahead of the outcome and
# 1 year behind the treatment, a proper temporal ordering rather than
# three contemporaneous series glued together. The total effect (c) and
# direct effect (c') both use Professionalisation(t-2) -> Turbulence(t),
# the same 2-year gap as path a, since c/c' answer "what does prof at t-2
# predict about turbulence at t" (with/without trust(t-1) in the model).
#
# METHOD: identical Baron & Kenny + Imai et al. (2010) mediate() pipeline
# and identical quadratic respec as 41o (path a stays linear; total effect
# c and direct effect c' on the Prof->Turbulence leg are quadratic) - only
# change is this lag structure.
#
# OUTPUT: console only - numbers to be hand-transcribed into a rebuilt
# build_fig_3_7_mediation.R, same as 41o's numbers were.

if (!require("pacman")) install.packages("pacman")
pacman::p_load(readr, tibble, mediation, dplyr)
select <- dplyr::select

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT

# ---- rebuild prof_pc1, identical to 41i/41o/49 ----
norm01 <- function(x) (x - min(x, na.rm=TRUE)) / (max(x, na.rm=TRUE) - min(x, na.rm=TRUE))
YEARS  <- 1979:2025
career_obs <- bind_rows(
  tribble(~year,~pct, 1979,3.0, 1983,4.5, 2010,14.0, 2015,17.0, 2019,21.0),
  tribble(~year,~pct, 1987,5.4, 1992,7.3, 1997,9.5, 2001,10.5, 2005,14.1)
) |> arrange(year)
career_annual <- tibble(year = YEARS) |>
  mutate(obs_yr = sapply(year, function(y) max(career_obs$year[career_obs$year <= y])),
         career_pct = career_obs$pct[match(obs_yr, career_obs$year)])
spads <- read_csv(file.path(PROJECT, "data/raw/spads_DATA_ENTRY.csv"), show_col_types = FALSE) |> filter(year <= 2025)
spads_annual <- tibble(year = YEARS, n_spads = approx(spads$year, spads$n_spads, xout = YEARS, rule = 2)$y)
ipsa  <- read_csv(file.path(PROJECT,"data/processed/ipsa_staffing_annual.csv"), show_col_types=FALSE) |> select(cal_year, staffing_real=mean_staffing_real_2015)
pre10 <- read_csv(file.path(PROJECT,"data/processed/staffing_pre2010_calibrated_butler.csv"), show_col_types=FALSE) |> filter(!is.na(real_2015_mean)) |> select(cal_year=year, staffing_real=real_2015_mean)
staffing_obs <- bind_rows(pre10, ipsa) |> arrange(cal_year) |> filter(cal_year <= 2025)
staffing_annual <- tibble(year = YEARS) |>
  mutate(obs_yr = sapply(year, function(y) max(staffing_obs$cal_year[staffing_obs$cal_year <= y])),
         staffing_real = staffing_obs$staffing_real[match(obs_yr, staffing_obs$cal_year)])
d_prof <- tibble(year = YEARS) |>
  left_join(career_annual |> select(year, career_pct), by="year") |>
  left_join(spads_annual |> select(year, n_spads), by="year") |>
  left_join(staffing_annual |> select(year, staffing_real), by="year") |>
  mutate(career_norm=norm01(career_pct), spads_norm=norm01(n_spads), staffing_norm=norm01(staffing_real))
pca_res <- prcomp(d_prof |> select(career_norm, spads_norm, staffing_norm), scale.=TRUE, center=TRUE)
d_prof  <- d_prof |> mutate(prof_pc1 = pca_res$x[,1])

trust <- read_csv(file.path(PROJECT, "data/processed/trust_extended_1979_2025.csv"), show_col_types = FALSE) |>
  select(year, trust_pct, data_source) |> mutate(observed = !grepl("INTERPOLATED", data_source, fixed = TRUE))
turb <- read_csv(file.path(PROJECT, "../composite_canonical/canonical_pc1_1979_2025.csv"), show_col_types = FALSE) |>
  select(year, turb_pc1 = PC1_index)

# ============================================================
# Build the sequential-lag frame: Prof(t-2), Trust(t-1), Turbulence(t)
# ============================================================
d <- tibble(year = YEARS) |>
  left_join(d_prof |> select(year, prof_pc1), by = "year") |>
  left_join(trust  |> select(year, trust_pct), by = "year") |>
  left_join(turb,                              by = "year") |>
  mutate(prof_lag2  = dplyr::lag(prof_pc1, 2),   # Prof at t-2
         trust_lag1 = dplyr::lag(trust_pct, 1)) |> # Trust at t-1 (= 1 yr after prof_lag2)
  filter(!is.na(prof_lag2), !is.na(trust_lag1), !is.na(turb_pc1))

cat(sprintf("N = %d, years %d-%d (Prof at t-2, Trust at t-1, Turbulence at t)\n\n",
            nrow(d), min(d$year), max(d$year)))

# ---- Step 1: total effect (c), quadratic — Prof(t-2) -> Turbulence(t) ----
eq_total <- lm(turb_pc1 ~ prof_lag2 + I(prof_lag2^2), data = d)
cat("=== Step 1: Total effect (c), QUADRATIC — Prof(t-2) (+^2) -> Turbulence(t) ===\n")
print(summary(eq_total)$coefficients)
cat(sprintf("R^2 = %.3f (vs linear-only R^2 = %.3f)\n", summary(eq_total)$r.squared,
            summary(lm(turb_pc1 ~ prof_lag2, data = d))$r.squared))

# ---- Step 2: path a — Prof(t-2) -> Trust(t-1), linear ----
eq_a <- lm(trust_lag1 ~ prof_lag2, data = d)
cat("\n=== Step 2: Path a — Prof(t-2) -> Trust(t-1) (linear) ===\n")
print(summary(eq_a)$coefficients)

# ---- Step 3: full model — Prof(t-2) (+^2) + Trust(t-1) -> Turbulence(t) ----
eq_full <- lm(turb_pc1 ~ prof_lag2 + I(prof_lag2^2) + trust_lag1, data = d)
cat("\n=== Step 3: Full model, QUADRATIC — Prof(t-2) (+^2) + Trust(t-1) -> Turbulence(t) ===\n")
print(summary(eq_full))

c1 <- coef(eq_total)["prof_lag2"]; c2 <- coef(eq_total)["I(prof_lag2^2)"]
cp1 <- coef(eq_full)["prof_lag2"]; cp2 <- coef(eq_full)["I(prof_lag2^2)"]
a_path <- coef(eq_a)["prof_lag2"]; b_path <- coef(eq_full)["trust_lag1"]
indirect <- a_path * b_path

cat(sprintf("\n=== Path summary (sequential lag: Prof[t-2]->Trust[t-1]->Turbulence[t]) ===\n"))
cat(sprintf("  Total effect (c):   linear=%.3f  quadratic=%.3f\n", c1, c2))
cat(sprintf("  Direct effect (c'): linear=%.3f  quadratic=%.3f\n", cp1, cp2))
cat(sprintf("  Path a (Prof[t-2]->Trust[t-1]): %.3f\n", a_path))
cat(sprintf("  Path b (Trust[t-1]->Turb[t]):   %.3f\n", b_path))
cat(sprintf("  Indirect (a x b):               %.3f\n", indirect))

cat("\n=== Mediation package: simulation-based indirect effect (quadratic outcome model) ===\n")
set.seed(42)
med_out <- mediate(eq_a, eq_full, treat = "prof_lag2", mediator = "trust_lag1", sims = 5000)
print(summary(med_out))

cat("\n=== Turning point of the direct-effect curve (holding trust at its mean) ===\n")
vertex <- -cp1 / (2*cp2)
cat(sprintf("Vertex at prof_lag2 = %.3f (data range: %.2f to %.2f)\n", vertex, min(d$prof_lag2), max(d$prof_lag2)))
